import type { Publication } from './publication-manifest';

export const nov10ResearchPublications: readonly Publication[] = [{"publicationStatus": "reviewed", "kind": "research", "slug": "how-often-do-assistant-handoffs-lack-an-acceptance-record", "title": "How often do assistant handoffs lack an acceptance record?", "description": "A review method for counting handoffs that never reached a confirmed receiver, and for separating a missing record from a missed deadline.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/how-often-do-assistant-handoffs-lack-an-acceptance-record-hero.webp", "thumbnail": "/thumbnails/november-10/how-often-do-assistant-handoffs-lack-an-acceptance-record.webp", "heroAlt": "How often do assistant handoffs lack an acceptance record?", "topic": "handoff acceptance", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/keep-a-handoff-acceptance-log-an-assistant-can-maintain", "label": "Read the handoff acceptance log guide"}, "sources": [{"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how often an assistant handoff reaches a receiver without a record of acceptance. The unit is a transfer of work that requires the receiver to act. The scope covers recurring client and internal workflows handled by a small assistant team. The review does not estimate a universal rate, because the definition of a handoff and the available records vary by team.", "The question matters because a sent message is often counted as a completed handoff. The sender sees the outbox, the queue clears, and the report shows the work as done. The receiver may never have opened the item or may be waiting for a file that did not arrive. The gap between sent and accepted is where work disappears.", "The review separates a missing acceptance record from a missed deadline. A handoff may be accepted on time but never logged, while another may be logged but accepted late. Both are failures, but one is a recordkeeping problem and the other is a service problem. Report them separately so the fix matches the cause."]}, {"id": "define-the-unit", "heading": "Define the unit and the population", "paragraphs": ["Define a handoff as a transfer where the receiver must produce an output, make a decision, or take the next step. A message sent only for information is out of scope. A transfer between two systems that no person must accept is also out of scope unless a person is expected to check the result. Write the definition before counting.", "Build the population from the task system, the shared inbox, and the handoff log. Match the records by work item or client reference. Include the items that moved through chat or a direct message when those channels are used for real work. A population built only from the formal tool will miss the informal transfers.", "Keep unresolved items in the denominator. An item with no acceptance record may be a missing row or a handoff that never happened. Dropping it would make the process look cleaner than it is. Mark the reason for the unresolved status and review a sample with the team."]}, {"id": "collect-the-evidence", "heading": "Collect the evidence", "paragraphs": ["For each handoff, capture the sender, the receiver, the send time, the acceptance time, the evidence transferred, and the next action. Add the reason for any return or condition. Record the source link for each field so a second reviewer can check the row. A row without a source is a claim rather than a record.", "Use a consistent definition of acceptance. It may be a written confirmation, a status change in the task system, or the start of work on the item. Choose one primary definition and record the alternatives as secondary evidence. Mixing definitions across rows makes the rate impossible to compare.", "Ask a second reviewer to check the rows that are marked missing. The reviewer should search the receiver's queue and the chat record before accepting the missing status. A quick search may find an acceptance that the first reviewer did not see. Record the result of the check with the row."]}, {"id": "measure-the-gap", "heading": "Measure the gap", "paragraphs": ["Report the share of handoffs with no acceptance record and the share accepted after the agreed window. Add the median wait and the oldest unresolved item. A single rate hides whether the problem is a few very old items or a broad pattern of missing confirmations. The distribution is more useful than the average.", "Compare the rate by workflow, sender, and receiver. A high rate in one workflow may point to an unclear trigger or a missing field. A high rate for one receiver may point to capacity or an unclear role. A rate that is spread across every group suggests the definition or the tool is the problem.", "Check the items that were closed without acceptance. A closure may be legitimate when the sender withdraws the work or the task is cancelled. Count those separately from a closure that assumes the receiver acted. A closed item with no evidence is the most expensive kind of missing record because no one is looking for it."]}, {"id": "interpret-with-care", "heading": "Interpret the pattern with care", "paragraphs": ["A missing record does not prove that the work was lost. The receiver may have acted on a verbal instruction or a message that the log does not capture. The review should describe the record, not the intent. Ask the team about the gaps before turning the number into a performance judgment.", "A high acceptance rate can also be misleading. The receiver may accept quickly without checking the evidence, and the work may fail later. Pair the acceptance rate with a small quality sample. Acceptance is a gate, not a guarantee that the handoff was complete.", "Look for the cases where the sender and receiver disagree about what was transferred. Those cases are often more informative than a simple missing row. They show where the definition of scope or evidence differs. Record the disagreement and use it to revise the brief."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Require an explicit acceptance step for the risky handoffs. The receiver should confirm the scope, the evidence, and the next date in one short message or status change. Make the step easy to complete from the task. A control that requires a separate form will be skipped on a busy day.", "Give the sender a way to see that the item was accepted. A queue that only shows sent items hides the gap. Add an accepted column and an age column. The sender can then follow up before the deadline rather than after the client complains.", "Set an automatic escalation when an item waits too long for acceptance. Send it to the queue owner with the original send time and the evidence. Do not rely on the sender to remember. The escalation should be part of the workflow, not a personal favor."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a local measurement method rather than a study of handoff rates across providers. The sources support records that are findable and accountable, but they do not supply a benchmark. The actual rate depends on the workflow, the tool, and the team's habits. A team should measure its own handoffs before setting a target.", "The log may change behavior while it is being kept. People may confirm more carefully or avoid the formal path. That effect can improve the process but makes the first period a weak baseline. Use a later period for comparison and note when the measurement began."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define a handoff and an acceptance separately. Build the population from every channel used for real work. Capture the sender, receiver, times, evidence, and next action. Check missing rows with a second reviewer.", "Report the missing rate, the late rate, and the age of unresolved items. Compare by workflow and receiver. Pair the rate with a quality sample. Add an acceptance column and an automatic escalation for long waits."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-exception-aging-reveal-about-queue-design", "title": "What does exception aging reveal about queue design?", "description": "How the age of unresolved exceptions exposes unclear ownership, missing evidence, and approval limits that a simple count cannot show.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/what-does-exception-aging-reveal-about-queue-design-hero.webp", "thumbnail": "/thumbnails/november-10/what-does-exception-aging-reveal-about-queue-design.webp", "heroAlt": "What does exception aging reveal about queue design?", "topic": "exception aging", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/run-a-daily-exception-queue-review", "label": "Read the daily exception queue review guide"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what the age of unresolved exceptions can reveal about the design of a work queue. The unit is an exception that entered the queue and has not been resolved. The scope covers recurring operational queues managed by an assistant or a small team. The review does not estimate a universal aging threshold, because the acceptable wait depends on the service and the risk.", "The question matters because a queue can look stable while its oldest items grow older. The total count stays the same as new items arrive and old items leave, but the slowest cases may be getting worse. Aging shows the pressure that a count hides. It also shows which cases are not moving at all.", "The review separates the age of an item from the time spent working on it. An item may be old because it waited for a client, an approval, or a missing document. The age alone does not prove that the team was slow. The reason for the wait is what turns the number into a management decision."]}, {"id": "define-the-clock", "heading": "Define when the clock starts", "paragraphs": ["Choose the event that starts the clock. It may be the moment the exception is identified, the moment it enters the queue, or the moment the first action is taken. Each definition produces a different age. Write the choice at the top of the report and use it for every row.", "Stop the clock only when the exception is resolved or explicitly accepted as a wait. A wait should have an owner and a return date. A pause without a date is a hidden closure. The report should show the waiting time separately from the working time.", "Decide how to handle an item that is reopened. Keep the original start date and add a reopened flag rather than resetting the clock. Resetting would make the item look new and hide the history. The reopened flag lets the team see both the total age and the current cycle."]}, {"id": "collect-the-reasons", "heading": "Collect the reasons for the wait", "paragraphs": ["Record a reason for every item that is older than the normal service time. Use a short list such as missing evidence, waiting on client, waiting on approval, unclear ownership, capacity, or system issue. The reason should describe the blocker, not the person. A short list is easier to apply consistently.", "Ask the person who worked the item to choose the reason at the time of the update. A reason added a week later is a reconstruction. If the reason is unclear, mark it as unknown rather than guessing. The unknown count is itself a finding about the queue's record quality.", "Add the date of the last action and the next planned action. An item with no next action is not being worked, even if it is assigned. That combination, old age plus no next action, is the strongest signal that the queue has lost ownership. It should be the first thing the daily review checks."]}, {"id": "analyze-the-distribution", "heading": "Analyze the distribution", "paragraphs": ["Report the median age, the oldest item, and the share older than the service standard. The median shows the normal experience, while the oldest item shows the tail. A queue with a good median and a very old tail may still be failing the clients who need the most help. Use both numbers.", "Group the age by reason and by owner. A large group waiting on one approval points to a bottleneck in that role. A large group with no owner points to an intake problem. A group waiting on the client may need a different follow-up cadence rather than more capacity.", "Compare the age of resolved items with the age of open items. If resolved items are young and open items are old, the team may be choosing the easy work first. That is a queue design issue, not necessarily a capacity issue. The comparison shows whether the order of work matches the risk."]}, {"id": "connect-to-design", "heading": "Connect the pattern to queue design", "paragraphs": ["An old item with unclear ownership points to a missing assignment rule. The queue may allow an item to sit in a general bucket without a named person. Add a default owner and a time limit for acceptance. The design change is more durable than a weekly reminder.", "An old item waiting on approval points to a threshold or a backup problem. The approver may be unavailable, or the threshold may require a review for work that is routine. Test a higher threshold for low-risk items and a named backup for the rest. Measure the age after the change.", "An old item waiting on missing evidence points to the intake form. The queue is holding work that should have been returned to the requester. Add a required field and a clear return path. The exception queue should not become the place where incomplete requests wait indefinitely."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Sort the daily review by age and risk rather than by arrival. Start with the oldest item and the item with the nearest client deadline. A queue sorted only by arrival can hide a small urgent item behind a large slow one. The sort order is a statement about what the team values.", "Set a service standard for each exception type and a review date for every wait. A wait without a date should be treated as an open action. The daily review should confirm the date or escalate the item. This prevents the queue from becoming a list of forgotten promises.", "Review the reasons each week and change one design element. If ownership is the main cause, add a default owner. If approval is the main cause, add a backup or a threshold. If evidence is the main cause, fix the intake. Then compare the next week's age with the same definitions."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes an aging analysis rather than a controlled study of queue designs. The data depends on what the team records and when. An item may be old because of a client delay that the team handled well. The age should be read with the reason and the service standard, not as a standalone score.", "The queue may also change while it is being reviewed. A backlog cleanup can make the age look better for a week without fixing the design. Use several weeks and note the cleanup. A sustained change in the reason pattern is stronger evidence than a one-time drop in the oldest item."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define the start event, the stop event, and the treatment of reopened items. Record a reason and a next action for every old item. Report the median, the oldest, and the share over the standard. Group the age by reason and owner.", "Compare resolved and open items to see whether the easy work is moving first. Fix the design element that matches the main reason. Set a service standard and a return date for every wait. Review the age again after one change."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-consistent-are-quality-reviews-across-assistant-teams", "title": "How consistent are quality reviews across assistant teams?", "description": "A method for comparing reviewers, scorecards, and sampled work so a quality score measures the work rather than the reviewer.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/how-consistent-are-quality-reviews-across-assistant-teams-hero.webp", "thumbnail": "/thumbnails/november-10/how-consistent-are-quality-reviews-across-assistant-teams.webp", "heroAlt": "How consistent are quality reviews across assistant teams?", "topic": "quality review consistency", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/set-a-quality-sample-review-cadence", "label": "Read the quality sample review cadence guide"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how consistent quality reviews are when several people score the same kind of assistant work. The unit is a scored work item, such as a ticket, a report, or a data entry batch. The scope covers recurring reviews in a small assistant team. The review does not estimate a universal reliability rate, because the standard and the work type vary by client.", "The question matters because a quality score is often used to compare people, teams, or providers. If two reviewers apply the same scorecard differently, the comparison measures the reviewer rather than the work. A score that cannot be reproduced is a weak basis for a staffing or contract decision. The comparison should test the scorecard before the scorecard is used to compare people.", "The review separates disagreement about the facts from disagreement about the standard. Two reviewers may see the same missing source and score it differently because the scorecard is unclear. They may also see different facts because one opened a file the other did not. The fixes are different, so the review should record both."]}, {"id": "design-the-comparison", "heading": "Design the comparison", "paragraphs": ["Select a set of work items that represent the normal range, including a few strong, weak, and borderline cases. Ask two or more reviewers to score each item independently using the current scorecard. Do not let them discuss the cases before scoring. The independence is what makes the comparison meaningful.", "Record the score, the evidence checked, and the reason for the score. A bare number cannot show why the reviewers differed. Ask each reviewer to note the first thing that shaped their judgment. That note often reveals a different interpretation of the standard.", "Compare the scores item by item rather than only the averages. Two reviewers can have the same average and disagree on every case. Count the exact matches, the adjacent scores, and the large gaps. The pattern shows whether the disagreement is random or concentrated in one part of the standard."]}, {"id": "find-the-sources-of-drift", "heading": "Find the sources of drift", "paragraphs": ["A common source of drift is an undefined score level. One reviewer treats a minor tone issue as a two, while another treats it as a three. The scorecard needs an example for each level. The example should describe the observable feature, not the overall impression.", "A second source is a different evidence set. One reviewer opens the source link and the other trusts the summary. The scorecard should require the same evidence for every item. If the evidence is unavailable, the item should be scored as incomplete rather than guessed.", "A third source is the reviewer's role. A manager may weight client risk more heavily, while a peer may weight speed. That difference can be legitimate, but it should be written into the standard. Otherwise the same work receives a different score depending on who reviews it."]}, {"id": "measure-agreement", "heading": "Measure agreement", "paragraphs": ["Report the share of items with an exact match and the share within one point. Add the cases with a large gap and the reason for each. A simple percentage is easier to explain than a statistical coefficient, especially when the sample is small. Use the measure that the team can act on.", "Look at the direction of the disagreement. If one reviewer consistently scores higher, the difference may be a calibration issue rather than random noise. If the disagreement is spread evenly, the standard may be ambiguous. The direction helps choose the next step.", "Repeat the comparison after the calibration session. A change in agreement shows whether the examples helped. Do not expect perfect agreement; some judgment is legitimate. The goal is a standard that produces similar results for similar work."]}, {"id": "use-the-result", "heading": "Use the result without overclaiming", "paragraphs": ["A consistency check is not a performance rating. A reviewer who disagrees may be applying a stricter reading that the team should adopt. The result should start a conversation about the standard, not a ranking of reviewers. Keep the scores and the discussion separate from pay or status.", "A high agreement rate does not prove that the standard is good. Reviewers can agree on a weak standard that misses an important risk. Pair the consistency check with a review of the standard against client complaints and rework. Agreement and validity are different questions.", "A low agreement rate does not prove that the work is bad. It may show that the scorecard is new or that the reviewers have not calibrated. Use a small set of examples and a short session before drawing a conclusion. The first comparison is a baseline, not a verdict."]}, {"id": "controls-that-improve-consistency", "heading": "Controls that improve consistency", "paragraphs": ["Write observable definitions for each score level and attach one example. Keep the scorecard short enough to use in a few minutes. Require the reviewer to record the evidence checked. A score without evidence cannot be calibrated.", "Calibrate new reviewers on the same sample before they review live work. Compare their scores with the standard and discuss the gaps. Repeat the calibration after a change in the standard or the work. A reviewer who joins without calibration will invent a local version of the scorecard.", "Audit a small sample of reviews each month and compare the scores with the evidence. Change one definition at a time and test the effect. Keep the review records in one place so the history is visible. Consistency is a maintenance habit, not a one-time training event."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a local comparison method rather than a study of quality review reliability across the industry. The sample is small and depends on the available work. The reviewers may change their scoring because they know they are being compared. That effect can improve consistency but makes the first round a weak baseline.", "The work itself may not be representative. A sample drawn from one week or one client may miss the cases that cause the most disagreement. Include the exceptions and the borderline cases. Report the limits of the sample beside the agreement rate."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Select a representative set of work and have reviewers score it independently. Record the score, the evidence, and the reason. Compare exact matches, adjacent scores, and large gaps. Look at the direction of the disagreement.", "Define each score level with an observable example. Calibrate new reviewers before live work. Audit a small sample each month and change one definition at a time. Keep the result separate from pay and status."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-often-does-source-of-truth-conflict-cause-rework", "title": "How often does a source-of-truth conflict cause rework?", "description": "A way to trace duplicate records, stale copies, and competing systems to the extra work they create, without blaming the person who found the conflict.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/how-often-does-source-of-truth-conflict-cause-rework-hero.webp", "thumbnail": "/thumbnails/november-10/how-often-does-source-of-truth-conflict-cause-rework.webp", "heroAlt": "How often does a source-of-truth conflict cause rework?", "topic": "source conflicts", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/map-the-source-of-truth-for-a-delegated-workflow", "label": "Read the source-of-truth map guide"}, "sources": [{"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how often a conflict between two sources of the same fact causes rework. The unit is a task that had to be redone, corrected, or clarified because two records disagreed. The scope covers recurring assistant workflows that read from a CRM, a billing system, a document store, or a client portal. The review does not estimate a universal rate, because the systems and the work mix vary.", "The question matters because a source conflict is often invisible until someone acts on the wrong value. A duplicate contact may cause a message to the wrong person, and a stale price may cause an incorrect quote. The correction takes time, and the client may lose confidence. The conflict is a process defect, not a one-off mistake.", "The review separates a conflict from a simple error. An error is a wrong value in one source, while a conflict is a disagreement between two sources that both look authoritative. A conflict may require a decision about which source wins. An error may only require a correction. The two need different controls."]}, {"id": "find-the-conflicts", "heading": "Find the conflicts", "paragraphs": ["Start with the tasks that were reopened or corrected in the past month. For each one, ask whether two sources disagreed. Record the systems, the fields, the values, and the source the team used. A short list of fields is enough to see the pattern. Do not try to reconcile every record at once.", "Check the fields that are most likely to conflict: contact details, legal names, payment information, prices, dates, and status. These fields change often and are copied into many places. A conflict in a stable field may be a one-time data error, while a conflict in a changing field may be a design problem. Record which field changes most often and who owns its update path.", "Include the informal sources that people actually use. A saved spreadsheet, an email thread, or a personal note can become the working truth even when the official system says something else. Record the informal source and why it was trusted. That reason is the clue to the fix."]}, {"id": "measure-the-rework", "heading": "Measure the rework", "paragraphs": ["For each conflict case, record the time spent finding the correct value, the time spent correcting the output, and the number of people involved. Add whether the client saw the error. A conflict that is caught before delivery is cheaper than one that reaches the client, but both consume capacity. Record the stage where the conflict was found so the report can show where the check is working.", "Report the count of conflict cases and the share of reopened tasks they represent. Add the most common field and the most common pair of systems. A count without a field is hard to act on. The field and the system pair point to the owner who can fix the source.", "Compare the rework from conflicts with the rework from other causes. If conflicts are a small share, a one-time cleanup may be enough. If they are a large share, the team needs a source map and a change to the update path. The comparison prevents over-investing in the wrong fix."]}, {"id": "why-conflicts-persist", "heading": "Why conflicts persist", "paragraphs": ["A conflict persists when two systems are both treated as official. The team may have moved to a new CRM without retiring the old spreadsheet. Each system has an owner, but no one owns the relationship between them. The result is a permanent race to see which value is used first.", "A conflict also persists when the update path is unclear. A person may update the CRM while another updates the billing tool, and neither knows the other exists. The field has two editors and no rule. Writing the allowed update path is more effective than asking people to be careful.", "A third cause is a convenience copy that outlives its purpose. A report exported for a meeting becomes the source for the next report. The copy drifts, but it looks familiar. Marking the copy with a refresh date and an owner helps, and retiring it is better when the source can be linked directly."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Name one source of truth for each field and publish the update path. The map should say who may edit, who must approve, and where the evidence goes. A field with two official sources will always conflict. The decision about which source wins is the control.", "Retire the copies that no longer have a purpose. For the copies that must stay, add a refresh date and a link to the source. A copy without a date is assumed to be current. The label should make its status obvious to a reader who was not there when it was created.", "Add a source check to the task where the conflict is most costly. A payment change, a legal name, or a price quote should require a second look at the official source. The check should be short and specific. A general instruction to verify is easy to skip."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a local tracing method rather than a study of data conflict rates across providers. The sample depends on the reopened tasks the team can find. Some conflicts are resolved silently before anyone records them, and some rework is never logged. Treat the result as a minimum count.", "The team may also change its behavior while the review is running. People may check the source more carefully or avoid the informal copy. That is a useful effect, but it makes the first period a weak baseline. Use a later period and note when the review began."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Sample reopened tasks and record whether two sources disagreed. Capture the systems, fields, values, and the source used. Measure the time and the people involved. Report the share of rework and the most common field.", "Name one source of truth for each field and publish the update path. Retire stale copies and label the ones that remain. Add a source check to the costliest tasks. Review the conflict pattern again after one change."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-share-of-access-grants-are-reviewed-on-schedule", "title": "What share of access grants are reviewed on schedule?", "description": "A method for counting late reviews, missing owners, and permissions that outlive the task, using the access list rather than a sample of memory.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/what-share-of-access-grants-are-reviewed-on-schedule-hero.webp", "thumbnail": "/thumbnails/november-10/what-share-of-access-grants-are-reviewed-on-schedule.webp", "heroAlt": "What share of access grants are reviewed on schedule?", "topic": "access review timing", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/build-a-client-access-recertification-checklist", "label": "Read the access recertification checklist guide"}, "sources": [{"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST SP 800-63B, Digital Identity Guidelines", "href": "https://pages.nist.gov/800-63-4/sp800-63b.html"}, {"label": "CISA Cyber Essentials", "href": "https://www.cisa.gov/cyber-essentials"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what share of access grants are reviewed by their scheduled date. The unit is one grant of access to one person for one client or system. The scope covers named accounts and shared links used by an assistant team. The review does not estimate a universal rate, because the review cycle and the risk level vary by client.", "The question matters because an access review that happens late is not the same as one that happens on time. A grant may be appropriate at the scheduled date and inappropriate a month later when the task ends. The delay is a window of unnecessary access. Counting the window makes the risk visible.", "The review separates a late review from a missing decision. A late review may still produce a keep or remove decision. A missing decision leaves the grant in place with no owner. The first is a scheduling problem, while the second is a governance problem. Report both so the fix is not just a reminder."]}, {"id": "build-the-list", "heading": "Build the list from the systems", "paragraphs": ["Start with the access list from each system rather than a list of people. Export the named accounts, the roles, the shared links, and the last sign-in date. Match the accounts to the client and the role. A list built only from the org chart will miss the service accounts and the shared mailboxes. Compare the export with the client contact list before counting the reviews.", "Record the grant date, the scheduled review date, the last review date, and the owner. Add the business reason and the task the access supports. A grant without a reason is a candidate for removal even when the person is active. The reason should be specific enough to test.", "Include the accounts that were created outside the normal request path. A tool may have invited a user directly, or a client may have shared a link without a ticket. Those grants are the easiest to miss and the most likely to outlive the work. Add them to the list before counting."]}, {"id": "define-on-schedule", "heading": "Define on-schedule", "paragraphs": ["Choose the scheduled date from the access policy or the client agreement. A quarterly review means the grant should be reviewed within the quarter, not on the last day. Write the rule and the grace period at the top of the report. A definition with no grace period may count a one-day delay the same as a year.", "Record the date the review was completed, not the date the ticket was opened. A ticket can sit open for weeks while the access remains unchanged. The completion date is when the decision was recorded and the change was made. Use the same definition for every row.", "Treat a review with no evidence as late. A note that says reviewed without a decision or a source is not a completed review. The report should show the missing evidence separately from a late review. That difference tells the team whether it needs a calendar or a better record."]}, {"id": "analyze-the-gaps", "heading": "Analyze the gaps", "paragraphs": ["Report the share reviewed on schedule, the share late, and the share with no review. Add the median delay and the oldest unreviewed grant. A high on-schedule rate with a few very old grants may be more dangerous than a moderate rate spread evenly. The tail matters because old access is often the least justified.", "Group the results by client, system, and owner. A client with many late reviews may have a different process or a missing contact. A system with many late reviews may not support a proper review export. An owner with many late reviews may have too many grants to manage.", "Compare the access list with the task list. A grant that supports a task that ended should be removed regardless of the review date. A grant that supports a current task should have a reason that matches the work. The comparison often finds access that is current in the calendar but obsolete in practice."]}, {"id": "interpret-the-result", "heading": "Interpret the result carefully", "paragraphs": ["A late review does not prove that the access was misused. It shows that the control was not applied on time. The team should look at the grants that were late and sensitive before drawing a conclusion. A late review of a read-only dashboard is different from a late review of an administrative account.", "A high on-schedule rate does not prove that the permissions are correct. The reviewer may have approved every grant without checking the work. Pair the timing with a sample of decisions. The sample should ask whether the permission still matches the task, not only whether the review happened.", "Look at the grants that were removed during the review. A high removal rate may mean the access was not maintained during the cycle. A low removal rate may mean the review is not challenging the status quo. Neither is automatically good. The pattern should be read with the task changes during the period."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Put the review date on the same calendar as the role review and the client check-in. A date that lives only in a spreadsheet is easy to postpone. Give the review a named owner and a backup. The owner should see the list before the date, not on the date.", "Make the decision easy to record. Use a short keep, reduce, remove, or repair choice with a reason and an evidence link. A reviewer who has to write a paragraph for every grant will delay the review. A simple form with a clear standard is more likely to be completed.", "Remove access when the task ends rather than waiting for the next cycle. The review is a backstop, not the only control. Add an offboarding step to the task closure. Test the removal with a sample of closed tasks. The best review is the one that finds less unnecessary access."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a local measurement method rather than a study of access review rates across providers. The sources define access control and identity good practice, not a benchmark. The actual rate depends on the client systems, the review cycle, and the records available. A team should measure its own list before setting a target.", "The access list may be incomplete. A direct invitation or an unmanaged link can create access that never appears in the export. The review should say which systems were included and which were not. A result based on a partial list is a floor, not a full census."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Build the list from each system, including shared links and direct invitations. Record the grant, scheduled review, last review, owner, reason, and task. Define on-schedule with a grace period and require evidence. Check the list against the client contact list before counting.", "Report the on-schedule share, the late share, and the unreviewed share. Group by client, system, and owner. Pair timing with a sample of decisions. Add an offboarding step and test removals after task closure."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-much-backup-coverage-capacity-goes-untested", "title": "How much backup coverage capacity goes untested?", "description": "A way to measure whether a named backup can actually cover the critical work, including access, instructions, and decision authority.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/how-much-backup-coverage-capacity-goes-untested-hero.webp", "thumbnail": "/thumbnails/november-10/how-much-backup-coverage-capacity-goes-untested.webp", "heroAlt": "How much backup coverage capacity goes untested?", "topic": "backup coverage", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/design-a-backup-coverage-drill-for-an-assistant-role", "label": "Read the backup coverage drill guide"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how much of a role's critical work has a backup who has been tested. The unit is a critical task that must continue during an absence. The scope covers assistant roles with recurring client deadlines and named coverage. The review does not estimate a universal coverage rate, because the critical work and the acceptable delay vary by role.", "The question matters because a backup plan often exists only on paper. A named person may lack the access, the instructions, or the authority to complete the work. The primary assistant may also be the only person who knows where the files live. A plan that has never been tested is a hope rather than a control.", "The review separates coverage capacity from coverage intent. Intent is the named backup in the plan. Capacity is the tested ability to complete the work within the service standard. A role can have a named backup and still have no real coverage. The review measures the capacity, not the name."]}, {"id": "select-the-critical-tasks", "heading": "Select the critical tasks", "paragraphs": ["List the tasks that cannot wait for the primary to return. Include the daily client update, the time-sensitive approval, the payment request, and the access change. Ask the client which tasks would cause a problem if they waited two days. The answer may differ from the internal list.", "Rank the tasks by the cost of a delay. A missed regulatory filing is different from a delayed internal report. Use the ranking to decide which tasks need a tested backup and which can wait. Not every task needs the same coverage. The ranking is a decision about where to spend the testing effort. A short list of truly critical tasks is easier to test and maintain.", "Write the service standard for each critical task. The standard should say how quickly the work must be completed and what evidence shows it was done. A backup who can do the task in twice the time may still fail the standard. The standard is part of the coverage definition."]}, {"id": "test-the-three-layers", "heading": "Test the three layers of coverage", "paragraphs": ["The first layer is access. The backup needs a named account, the right permission, and a working second factor. Test the login and the specific action, not only the account status. A backup who can open the tool but cannot approve the request is not covered.", "The second layer is instruction. The backup needs a current runbook that they can find without the primary. Test the search path from the place the backup actually starts. A document in the primary's personal folder is not a runbook. The instructions should name the source, the steps, and the escalation contact.", "The third layer is authority. The backup needs permission to make the decisions the task requires. A backup who must ask the primary for every approval is not available when the primary is absent. Name the decisions the backup may make and the ones that need another owner. Record the authority in the plan."]}, {"id": "measure-the-result", "heading": "Measure the result", "paragraphs": ["For each critical task, record whether the backup completed it, the time taken, the questions asked, and the errors found. A completion without the standard is not full coverage. Report the partial cases separately. The pattern shows which layer is missing.", "Calculate the share of critical tasks with tested coverage and the share with a named but untested backup. Add the share with no backup at all. The three numbers tell a more useful story than a single coverage percentage. A team may have names for every task and tests for none.", "Compare the drill time with the normal time. A backup who takes much longer may still be acceptable for a low-frequency task but not for a daily one. Use the service standard to decide. The comparison also shows where the runbook or the tool is slowing the backup down."]}, {"id": "interpret-the-gaps", "heading": "Interpret the gaps", "paragraphs": ["An access gap is usually the easiest to fix, but it can also be the most sensitive. Grant the minimum permission for the task and remove it after the drill. Do not leave permanent broad access just to make the backup plan look complete. The temporary grant should have an owner and an expiry.", "An instruction gap points to the runbook or the search path. A backup who could not find the document may still know the work from experience. The test should use a person who does not have that experience, or the result will overstate the coverage. Write the runbook for the person who was not there.", "An authority gap is a management decision. The backup may need approval authority for a limited set of actions during an absence. Write the delegation, the limit, and the end date. A verbal permission is hard to prove when a client or an auditor asks who approved the work."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Run a drill on a fixed cadence and record the result. Start with one critical task and one named backup. Test the access, the instruction, and the authority in the same exercise. A small, regular drill is more useful than a large annual rehearsal.", "Keep the runbook in the shared workspace and link it from the task. Review it after every drill and after any change in the client or the tool. Assign an owner and a review date. A runbook without a date is assumed to be current even when it is not.", "Give the backup a way to escalate a gap without blame. The drill should surface problems, not punish the person who finds them. Record the gap and the repair. The next drill should test the repair, not repeat the same discovery."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a local coverage assessment rather than a study of backup capacity across providers. The sample depends on the tasks the team identifies and the people available to test them. A drill with a knowledgeable backup may overstate the coverage. A drill with an inexperienced backup may understate it.", "The drill can also change behavior. People may prepare more carefully because they know the test is coming. That is a useful effect, but it makes the first result a weak baseline. Repeat the drill and use the later result for comparison. Note the date of the first test."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["List the critical tasks and rank them by the cost of a delay. Write the service standard and the evidence of completion. Name the backup and the decisions they may make. Record the date the list was last reviewed.", "Test access, instruction, and authority in one drill. Record completion, time, questions, and errors. Report tested, named-but-untested, and no-backup shares. Repair the missing layer and test again."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-often-do-weekly-decision-briefs-change-a-decision", "title": "How often do weekly decision briefs change a decision?", "description": "A method for tracing a brief from request to outcome, so the team can see whether it informs a choice or only documents activity.", "published": "2026-11-10", "readingMinutes": 8, "heroImage": "/hero/november-10/how-often-do-weekly-decision-briefs-change-a-decision-hero.webp", "thumbnail": "/thumbnails/november-10/how-often-do-weekly-decision-briefs-change-a-decision.webp", "heroAlt": "How often do weekly decision briefs change a decision?", "topic": "decision briefs", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/assemble-a-weekly-decision-brief-from-open-work", "label": "Read the weekly decision brief guide"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}, {"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how often a weekly decision brief leads to a recorded decision. The unit is one decision requested in a brief. The scope covers briefs prepared for an executive, a client owner, or a team lead in a recurring assistant workflow. The review does not estimate a universal rate, because the decision type and the meeting rhythm vary.", "The question matters because a brief can look useful while changing nothing. The reader may appreciate the summary, the meeting may discuss it, and the same item may return next week. A brief that does not produce a decision is a report, not a decision tool. Counting the outcome shows whether the format earns its place.", "The review separates a decision from an action. A decision is a choice between options, while an action is a task that follows. A brief may produce a task without resolving the underlying choice. Count the decisions separately so the team does not confuse movement with resolution."]}, {"id": "define-the-outcome", "heading": "Define the outcome", "paragraphs": ["For each requested decision, record what was asked, who owned it, and when an answer was needed. Then record what happened: approved, rejected, deferred, replaced by another option, or no response. Use a short list of outcomes and apply it consistently. A vague note that the item was discussed is not an outcome.", "A deferred decision is still an outcome if it has a new date and an owner. A deferred item without a date is a no-response. Treat the two differently in the report. The first is a choice to wait, while the second is a process failure.", "Record the decision date and the evidence that shows it was made. The evidence may be a signed approval, a meeting note, or a status change in the task. A decision that exists only in conversation is hard to verify. Use the best available record and note its limits."]}, {"id": "trace-the-brief", "heading": "Trace the brief to the decision", "paragraphs": ["Match each brief item to the decision record and the work that followed. Look for the item in the next week's brief, the task system, and the client update. A decision that appears in the brief but not in the work may not have been communicated. A decision that appears in the work but not in the brief may have been made elsewhere.", "Ask the decision owner what they used from the brief. The answer may show that the recommendation was helpful, the evidence was ignored, or the question was already settled. Record the answer without defending the brief. The purpose is to learn what the reader needs, not to prove the work was good.", "Check the items that were dropped without a decision. A dropped item may be lower priority, or it may have been forgotten. Compare it with the next brief and the client record. A pattern of dropped items suggests that the brief is too long or the owner is not engaged."]}, {"id": "measure-the-effect", "heading": "Measure the effect", "paragraphs": ["Report the share of items with a recorded decision, the share deferred with a date, and the share with no response. Add the median time from request to decision. A high decision rate with a long delay may still be a problem. The time shows whether the brief is helping the team act before a deadline.", "Group the results by decision type, owner, and week. A type that is rarely decided may need a different owner or a smaller ask. An owner who decides quickly may be getting better evidence. A week with no decisions may be a quiet week or a brief that arrived too late.", "Compare the decisions with the outcomes. A decision that is made but not implemented is not the same as one that changes the work. Trace a sample of decisions to the next action and the result. The brief should support a choice that leads to a change, not only a choice in a meeting."]}, {"id": "interpret-with-care", "heading": "Interpret the result carefully", "paragraphs": ["A low decision rate does not prove that the brief is poorly written. The owner may be unavailable, the options may be incomplete, or the decision may need a client input that has not arrived. The review should record the reason before judging the format. A brief cannot fix an absent decision-maker.", "A high decision rate does not prove that the decisions are good. The owner may be approving everything to clear the list. Pair the rate with a small quality review of the decisions and their outcomes. Speed and quality are different measures.", "Look at the decisions that were replaced by another option. A replaced option may show that the brief framed the choice too narrowly. It may also show that the owner had information the writer did not. Record the new option and use it to improve the next brief."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Ask for a decision only when a real choice exists and the owner can make it. A brief that asks for direction without options creates work for the reader. Write two or three clear options with the cost and the risk. A specific ask is easier to answer than a general request.", "Put the decision owner and the needed date at the top of each item. A brief that hides the ask in the fourth paragraph will be skimmed. Use the same format every week so the reader knows where to look. The format should make the decision visible, not decorate it.", "Close the loop in the next brief. Show what was decided, what changed, and what is still open. A reader who sees the follow-through is more likely to engage with the next ask. A brief that never returns to the previous decisions becomes a one-way report."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a local tracing method rather than a study of decision brief effectiveness across organizations. The sample depends on the records the team keeps and the access to the decision owner. Some decisions are made in conversation and never recorded. The result is a floor rather than a complete count.", "The team may also change its behavior while the review is running. Owners may decide more quickly because they know the brief is being tracked. That effect can be useful, but it makes the first period a weak baseline. Use a later period and note when the review began."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define a decision and an action separately. Record the ask, the owner, the date needed, and the outcome. Trace each item to the decision record and the next action. Measure the time from request to decision.", "Group the results by type, owner, and week. Ask the owner what they used. Close the loop in the next brief. Change one part of the format and compare the next cycle."]}]}];
